Problem:
Architects ABC has a budget of one hundred thousand dollars to spend every week on their employees. They hire architects and drafters to help with their clients’ projects. An architect averages 3000 dollars every week and can complete 2 projects every week. A drafter does not have all the certifications and requires an architect for supervision at all times. Therefore, there must be more architects than drafters. Additionally, a drafter averages 1200 dollars every week and completes 1 project every week. How many architects and drafters should be contracted to maximize the number of projects completed every week?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "architects hired",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "drafters hired",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "architects hired",
     "coef": 2.0
    },
    {
     "var": "drafters hired",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "weekly budget",
    "terms": [
     {
      "var": "architects hired",
      "coef": 3000.0
     },
     {
      "var": "drafters hired",
      "coef": 1200.0
     }
    ],
    "sense": "<=",
    "rhs": 100000.0
   },
   {
    "name": "more architects than drafters",
    "terms": [
     {
      "var": "architects hired",
      "coef": 1.0
     },
     {
      "var": "drafters hired",
      "coef": -1.0
     }
    ],
    "sense": ">=",
    "rhs": 1.0
   }
  ]
 },
 "facts": {
  "objective": 71.0,
  "values": {
   "architects hired": 24.0,
   "drafters hired": 23.0
  },
  "binding": [
   "more architects than drafters"
  ],
  "slack": {
   "weekly budget": 400.0,
   "more architects than drafters": 0.0
  },
  "shadow_prices": null
 }
}
